// Typed access to the JSON generated by scripts/extract-rathena.ts.

import attrFixJson from "../data/attrFix.json";
import jobsJson from "../data/jobs.json";
import refineJson from "../data/refine.json";
import sizeFixJson from "../data/sizeFix.json";
import statPointsJson from "../data/statPoints.json";
import targetPresetsJson from "../data/targetPresets.json";

export type Size = "Small" | "Medium" | "Large";
export const SIZES: readonly Size[] = ["Small", "Medium", "Large"];

export const ELEMENTS = ["Neutral", "Water", "Earth", "Fire", "Wind", "Poison", "Holy", "Dark", "Ghost", "Undead"] as const;
export type Element = (typeof ELEMENTS)[number];

export type StatName = "Str" | "Agi" | "Vit" | "Int" | "Dex" | "Luk";
export const STAT_NAMES: readonly StatName[] = ["Str", "Agi", "Vit", "Int", "Dex", "Luk"];

export type JobName = "Novice_High" | "Swordman_High" | "Knight" | "Lord_Knight";

export interface JobData {
  job: JobName;
  baseAspd: Partial<Record<string, number>>;
  bonusStats: { level: number; stats: Partial<Record<StatName, number>> }[];
}

export const jobs = jobsJson as JobData[];

/** Cumulative status points by base level (index = level - 1), before the transcendent bonus. */
export const statPoints: readonly number[] = statPointsJson;

/** Damage % by weapon type and target size (size_fix.yml). */
export const sizeFix = sizeFixJson as Record<string, Record<Size, number>>;

/** Element damage %: attrFix[defenseElementLevel][attackElement][defenseElement] (attr_fix.yml). */
export const attrFix = attrFixJson as Record<string, Record<Element, Record<Element, number>>>;

/** Weapon refine ATK: refine[weaponLevel][refine] (refine.yml). */
export const refine = refineJson as Record<string, { bonus: number; randomBonus: number }[]>;

export interface TargetPresetData {
  size: Size;
  sampleSize: number;
  level: number;
  hp: number;
  def: number;
  vit: number;
  agi: number;
  luk: number;
  race: string;
  element: Element;
  elementLevel: number;
}

export const targetPresets = targetPresetsJson as TargetPresetData[];

export function getJob(job: JobName): JobData {
  const data = jobs.find((j) => j.job === job);
  if (!data) throw new Error(`Unknown job ${job}`);
  return data;
}
